4	//! OpenAI clients, assemble the shared [`AppState`], serve `/healthz`+`/readyz` and the protected
5	//! `/v1/chat/completions` proxy on one HTTP port, and shut down gracefully on SIGINT/SIGTERM. The
6	//! gateway is simpler than `paigasus-iam` — one HTTP port, no gRPC server, no DB, no background
7	//! relays.
8	
9	use std::sync::Arc;
10	use std::time::Duration;
11	
12	use paigasus_gateway::adapters::http::{AppState, router};
13	use paigasus_gateway::adapters::iam::IamClient;
14	use paigasus_gateway::adapters::openai::OpenAiClient;
15	use paigasus_gateway::config::GatewayConfig;
16	
17	#[tokio::main]
18	async fn main() -> anyhow::Result<()> {
19	    let config = GatewayConfig::load()?;
20	    config.validate().map_err(anyhow::Error::msg)?;
21	    paigasus_logging::init("paigasus-gateway", &config.log_level);
22	
23	    // Outbound clients. IAM connects lazily (a dead IAM does not block startup); the OpenAI client
24	    // is built with the three split timeout budgets. Neither construction logs the key.
25	    let iam = IamClient::connect(&config.iam).await?;
26	    let openai = OpenAiClient::new(
27	        &config.upstream.openai,
28	        Duration::from_secs(config.connect_timeout_secs),
29	        Duration::from_secs(config.first_byte_timeout_secs),
30	        Duration::from_secs(config.stream_idle_timeout_secs),
31	    )?;
32	
33	    let state = AppState {
34	        iam: Arc::new(iam),
35	        openai: Arc::new(openai),
36	        max_request_bytes: config.max_request_bytes,
37	    };
38	
39	    let app = router(state);
40	    let listener = tokio::net::TcpListener::bind(config.http_addr).await?;
41	    tracing::info!(%config.http_addr, "paigasus-gateway started");
42	    axum::serve(listener, app).with_graceful_shutdown(shutdown_signal()).await?;
43	
44	    Ok(())
45	}
46	
47	async fn shutdown_signal() {
48	    let ctrl_c = async {
49	        tokio::signal::ctrl_c().await.expect("install Ctrl+C handler");
50	    };
51	    #[cfg(unix)]
52	    let terminate = async {
53	        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("install SIGTERM handler").recv().await;
54	    };
55	    #[cfg(not(unix))]
56	    let terminate = std::future::pending::<()>();
57	
58	    tokio::select! {
59	        () = ctrl_c => {},
60	        () = terminate => {},
61	    }
62	}
