29	/// Deliberately-INVALID sentinel token for the `/readyz` IAM-reachability probe. It has no
30	/// `pgs_sk_` prefix, so a REACHABLE IAM parses and rejects it (an application-level `Status`, e.g.
31	/// `Unauthenticated`) while an UNREACHABLE IAM fails at the transport. It authenticates nothing —
32	/// the introspect is a cheap, unaudited parse-reject, never a real credential.
33	const READYZ_PROBE_TOKEN: &str = "readyz-probe";
34	
35	/// Shared handler state: the IAM port (an `Arc<dyn Iam>` so tests inject a fake and the binary
36	/// injects the real `IamClient`), the OpenAI egress client, and the inbound body-size cap. `Clone`
37	/// is cheap (all fields are `Arc`/`Copy`), as axum requires for `State`.
38	#[derive(Clone)]
39	pub struct AppState {
40	    /// The IAM port the auth middleware queries (introspect + self-query authorize).
41	    pub iam: Arc<dyn Iam>,
42	    /// The outbound OpenAI egress client (holds the real key; forwards raw request bytes).
43	    pub openai: Arc<OpenAiClient>,
44	    /// Max inbound request-body size in bytes; an over-limit body is rejected with `413`.
45	    pub max_request_bytes: usize,
46	}
