48	/// The gateway's HTTP surface. `/healthz` + `/readyz` are public (no auth, no body limit); the
49	/// `/v1/chat/completions` proxy is protected by the G5 auth middleware and a
50	/// [`DefaultBodyLimit`] cap. The auth + body-limit are applied via [`Router::route_layer`], which
51	/// runs the layers ONLY for the matched protected route — so the health probes stay outside auth
52	/// AND the body limit, and an unmatched path still 404s without first being challenged for a
53	/// credential.
54	///
55	/// The shared [`AppState`] is applied ONCE, at the end, over the whole tree so both the stateful
56	/// `readyz` (it probes IAM) and the protected chat handler read the same state. `healthz` takes no
57	/// state — a stateless handler is still valid inside a stateful router.
58	pub fn router(state: AppState) -> Router {
59	    // The auth middleware's state is the IAM port alone (`Arc<dyn Iam>`), captured here BEFORE the
60	    // final `with_state`, and independent of the handler's `AppState` — so this clone is just the
61	    // port, not the whole state.
62	    let auth = axum::middleware::from_fn_with_state(state.iam.clone(), require_iam_auth);
63	    // The body-size limit: an over-limit body fails the handler's `Bytes` extractor with `413`.
64	    // Note (M0): auth runs BEFORE the 413 (the limit is enforced at body extraction, after the
65	    // middleware) — acceptable here since auth reads only headers, never the body.
66	    let body_limit = DefaultBodyLimit::max(state.max_request_bytes);
67	
68	    let protected = Router::new().route("/v1/chat/completions", post(chat::chat_completions)).route_layer(auth).route_layer(body_limit);
69	
70	    Router::new().route("/healthz", get(healthz)).route("/readyz", get(readyz)).merge(protected).with_state(state)
71	}
